    'saved_notice' => [
        'sources_label' => 'Sources',
        'archived' => 'Archived',
        'page_help_button' => 'Help',
        'page_help_title' => 'About this case',
        'page_help_intro' => 'This is the workspace for one saved notice. Here you coordinate ownership, deadlines, documents and bid work.',
        'page_help_section_overview' => 'What this page is used for',
        'page_help_item_status_title' => 'Status and ownership',
        'page_help_item_status_text' => 'The status panel shows where the case stands right now, and the actions beside it show what you can do next. This is also where you assign a bid manager and commercial owner.',
        'page_help_item_documents_title' => 'Documents',
        'page_help_item_documents_text' => 'The notice documents are listed for download, one by one or all at once. Uploading and AI work on the documents happen behind "Open case documents and AI".',
        'case_documents_cta_label' => 'Open case documents and AI',
        'case_documents_cta_help' => 'Upload and work with documents related to this specific case.',
        'page_help_item_comments_title' => 'Phase comments',
        'page_help_item_comments_text' => 'Notes tied to the phase the case was in when they were written. Use them for context and reasoning along the way, not to restate the status.',
        'page_help_section_go_no_go' => 'The Go / No-Go phase',
        'page_help_item_go_no_go_phase_title' => 'The decision point',
        'page_help_item_go_no_go_phase_text' => 'Go / No-Go is where you decide whether to pursue the case. There are two ways forward: move on to bid work, or set the case to No-Go.',
        'page_help_item_go_no_go_set_title' => 'Setting a case to No-Go',
        'page_help_item_go_no_go_set_text' => 'The action opens a short form where you pick the reason for stopping the case. A reason is required. You can add a closing note as well, but that is optional. The case is closed only once you confirm.',
        'page_help_item_go_no_go_meaning_title' => 'What No-Go means',
        'page_help_item_go_no_go_meaning_text' => 'The case is closed as No-Go and ordinary bid work stops. After No-Go there are no regular next status choices – the case does not move on by itself.',
        'page_help_section_no_go_decision' => 'The No-Go decision and reopening',
        'page_help_item_no_go_decision_title' => 'The "No-Go decision" section',
        'page_help_item_no_go_decision_text' => 'This section appears only once the case is actually set to No-Go. It shows the reason, the closing note, who made the decision, and any earlier reopenings.',
        'page_help_item_reopen_when_title' => 'When circumstances change',
        'page_help_item_reopen_when_text' => 'A No-Go decision can be reversed if the picture changes. "Reopen case" is a deliberate action outside the ordinary status flow: you write a justification and confirm, and the case returns to Go / No-Go so the decision can be made again.',
        'page_help_item_reopen_history_title' => 'The history is kept',
        'page_help_item_reopen_history_text' => 'The original No-Go decision is not deleted. The reason, the note and the justification for reopening stay on the case as decision history.',
        'page_help_item_reopen_access_title' => 'Who can reopen a case',
        'page_help_item_reopen_access_text' => 'Reopening requires responsibility for the case. A System Owner can reopen cases they have access to, and a bid manager can reopen cases they are responsible for. Others still see the decision, but without the reopen action.',
        'page_help_section_archiving' => 'History and No-Go',
        'page_help_item_archiving_move_title' => '"Move to history"',
        'page_help_item_archiving_move_text' => 'Moves the case out of the active work list. The case is kept and can still be opened and read in History, but it cannot be moved back to the active work list. You have to confirm the action in a dialog first.',
        'page_help_item_archiving_difference_title' => 'No-Go and History',
        'page_help_item_archiving_difference_text' => 'No-Go is a bid decision to stop the bid work. History is where a case is filed for good in the ordinary workflow. A case can be set to No-Go without sitting in History, and it can sit in History without being No-Go.',
        'page_help_item_archiving_no_go_title' => 'An archived No-Go case',
        'page_help_item_archiving_no_go_text' => 'An archived No-Go case is the exception. If the No-Go decision is later reversed, a user with the necessary access can use "Reopen case". That is a separate, audited decision with a justification – not an ordinary restore from History.',
