        'help' => [
            'button' => 'Help',
            'index' => [
                'title' => 'About supplier follow-up',
                'intro' => 'Here you have an overview of the suppliers the organisation depends on: what they deliver, who in your organisation follows them up, and whether they are in use.',
                'sections' => [
                    [
                        'title' => 'The suppliers',
                        'items' => [
                            ['title' => 'One supplier, once', 'text' => 'Each supplier is registered once, as the company it is – not once per contract, service or document. If it delivers several things, describe them in «What do they deliver to us?».'],
                            ['title' => 'Internal owner', 'text' => 'Each supplier has a person in your organisation who follows it up. Ownership grants no extra access.'],
                            ['title' => 'Category', 'text' => 'The category makes the register easier to filter. Choose the one that fits best.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Under review', 'text' => 'Registered, but not taken into use.'],
                            ['title' => 'Active', 'text' => 'The supplier is in use.'],
                            ['title' => 'Ended', 'text' => 'The supplier is no longer in use, or was not chosen. Ended suppliers are shown when you choose «All statuses» or «Ended».'],
                        ],
                    ],
                    [
                        'title' => 'Criticality',
                        'items' => [
                            ['title' => 'Standard, Important or Critical', 'text' => 'Criticality says how important the supplier is to the organisation. You choose the level yourselves; four yes/no questions are the basis for the choice, but are not turned into any level.'],
                            ['title' => 'Not assessed', 'text' => 'The supplier has no criticality yet. Open the supplier and choose «Assess criticality».'],
                        ],
                    ],
                    [
                        'title' => 'Needs attention',
                        'items' => [
                            ['title' => 'What is shown', 'text' => 'Suppliers that are not ended and have something concrete to follow up: an active Important or Critical supplier without a supplier assessment, a supplier assessment that is overdue, no internal owner, or documentation that has expired or expires within 60 days. With control requirements, also: requires decision, control overdue, mandatory or important requirements not controlled, important or critical suppliers without a filled-in profile, and due diligence assessments that are missing or overdue.'],
                            ['title' => 'Only the supplier\'s own information', 'text' => 'The list is based only on what is registered here. Risks, requirements and cases in other modules do not affect it. Once the supplier is followed up, it leaves the list.'],
                            ['title' => 'Control status', 'text' => 'The column shows the latest decision about the supplier and, separately, whether the supplier requires a decision because a mandatory control requirement is open. The system never approves a supplier by itself.'],
                        ],
                    ],
                    [
                        'title' => 'Access',
                        'items' => [
                            ['title' => 'Permissions', 'text' => 'Who can view, register and delete suppliers is decided by the roles under Access in the customer environment.'],
                            ['title' => 'System Owner', 'text' => 'System Owner does not get access automatically. To work here, give yourself a role with the permissions.'],
                        ],
                    ],
                ],
            ],
            'control_requirements' => [
                'title' => 'About control requirements',
                'intro' => 'The control requirements are the requirements you set for suppliers, and how they are controlled.',
                'sections' => [
                    [
                        'title' => 'Which suppliers a requirement applies to',
                        'items' => [
                            ['title' => 'All or some', 'text' => 'A requirement applies to all suppliers, or to suppliers where at least one of the conditions you choose applies according to the supplier profile. You can also limit it to important and critical suppliers.'],
                            ['title' => 'Not clarified', 'text' => 'If a condition is «Not clarified» in the profile, the requirement applies. If the profile has not been filled in at all, only requirements that follow from the criticality apply.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement level',
                        'items' => [
                            ['title' => 'Mandatory, Important or Follow-up', 'text' => 'Mandatory requirements cannot be excluded for a single supplier. If a mandatory requirement applies wrongly, correct the profile or the requirement.'],
                        ],
                    ],
                    [
                        'title' => 'Changing and retiring',
                        'items' => [
                            ['title' => 'Mark as retired', 'text' => 'A retired requirement applies to no supplier. Manual decisions and history are kept. A requirement that has never been used can be deleted.'],
                            ['title' => 'Anchor', 'text' => 'A requirement can be anchored in a requirement in Compliance and audit. The anchor is optional and shown only to people with access there. The basis is always written in the requirement itself.'],
                            ['title' => 'Access', 'text' => 'Everyone with access to Supplier management can see the requirements. Only roles with the supplier assurance permission can change them.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement templates',
                        'items' => [
                            ['title' => 'A starting point', 'text' => 'The templates are starting points for different types of supplier, and you can use several of them. A template adds the control requirements you do not already have. A requirement that is already there – also from another template – is not added again, and your own requirements are not changed.'],
                            ['title' => 'The requirements are yours', 'text' => 'Requirements from a template can be edited, retired or deleted like any other control requirement. A newer version of the template does not change them.'],
                            ['title' => 'Typical basis', 'text' => 'The templates describe typical supplier requirements, not a legal answer. Assess them against your own agreements and obligations. The requirements must still be controlled, and the decisions are made by people.'],
                        ],
                    ],
                ],
            ],
            'supplier' => [
                'title' => 'About the supplier',
                'intro' => 'The supplier page brings together what you know about the supplier, who follows it up, and what has happened to it.',
                'sections' => [
                    [
                        'title' => 'How the page is organised',
                        'items' => [
                            ['title' => 'Overview', 'text' => 'Control status is at the top of every tab. Overview gathers what needs attention, the supplier, criticality and profile, security and privacy, short summaries and the next controls. From here you take the supplier into use, end it or reopen it.'],
                            ['title' => 'The tabs', 'text' => 'Requirements and qualifications, Documentation, Assessments and Due diligence hold the lists, the history and the actions. The links in Needs attention and Next controls open the right tab.'],
                            ['title' => 'Decision and State now', 'text' => 'The decision is a person\'s, with a date and a reason. State now is computed from the requirements and controls. They are shown apart, and an earlier decision can stand while the state has changed.'],
                        ],
                    ],
                    [
                        'title' => 'Security and privacy',
                        'items' => [
                            ['title' => 'What the card shows', 'text' => 'The profile facts that make security, privacy and continuity requirements apply – personal data, access, where the data is processed and subcontractors – and the status of each of those requirements now.'],
                            ['title' => 'No overall rating', 'text' => 'The card is an extract of Requirements and qualifications. It gives no points or overall status, and it does not approve the supplier.'],
                            ['title' => 'Requirement templates', 'text' => 'The requirements come from your control requirements, often from a requirement template. Templates are applied under Control requirements; each requirement\'s level is changed there.'],
                        ],
                    ],
                    [
                        'title' => 'From registered to ended',
                        'items' => [
                            ['title' => 'Take into use', 'text' => 'A supplier under review becomes active when you take it into use.'],
                            ['title' => 'End supplier', 'text' => 'When the supplier is no longer in use, or was not chosen, end it with a reason. The supplier can then not be changed, but everything registered stays.'],
                            ['title' => 'Reopen supplier', 'text' => 'An ended supplier can be reopened with a reason. It becomes active again and can be changed.'],
                        ],
                    ],
                    [
                        'title' => 'Criticality',
                        'items' => [
                            ['title' => 'How important is the supplier?', 'text' => 'Choose Standard, Important or Critical. The four yes/no questions are the basis for the choice and are saved with it, but the system neither calculates nor suggests a level.'],
                            ['title' => 'Review interval', 'text' => 'How often the supplier should be reviewed. Important and critical suppliers must have an interval.'],
                            ['title' => 'Change criticality', 'text' => 'Every change requires a reason and is saved in the history with the level, interval and answers before and after. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'Supplier profile',
                        'items' => [
                            ['title' => 'What the profile is', 'text' => 'The profile describes the circumstances of the delivery – data, access, supply chain, work and contract terms. It will later decide which control requirements apply to the supplier. It is not an assessment of the supplier.'],
                            ['title' => 'Yes, No or Not clarified', 'text' => 'Choose «Not clarified» when you do not know the answer yet. It is not the same as «No»: something not clarified is treated as if it applies.'],
                            ['title' => 'Changing the profile', 'text' => 'Filling it in the first time needs no reason. Later changes require a reason and are saved in the profile history with the answers before and after. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'Requirements and qualifications',
                        'items' => [
                            ['title' => 'Which requirements apply?', 'text' => 'The control requirements that apply to the supplier are worked out from the supplier profile and the criticality every time the page opens. Change the profile, and the requirements change at once.'],
                            ['title' => 'Applies because …', 'text' => 'Each requirement shows why it applies. A condition that is «Not clarified» in the profile counts as applying, and the reason then says it is not clarified.'],
                            ['title' => 'Adding or excluding a requirement', 'text' => 'With the supplier assurance permission you can add a requirement that does not apply automatically, or exclude one that does. Both need a reason and are kept in the history. Mandatory requirements cannot be excluded. «Back to automatic assessment» lifts the decision.'],
                            ['title' => 'Documentation is the basis', 'text' => 'When you control a requirement, you choose the documentation you relied on. Documentation is registered under Documentation. Choosing a document does not mean the requirement is met.'],
                            ['title' => 'The controller judges', 'text' => 'You decide whether the documentation covers the requirement: Documented, Partially documented, Missing or Temporarily accepted until a date. The system never sets the result itself. «Documented» needs at least one document, and every result needs a reason.'],
                            ['title' => 'The history does not change', 'text' => 'A control cannot be changed or deleted. If it is wrong, register a new one. The control shows the documentation as it was registered then, even if the document changes later. «Renewal due» shows when the control interval has passed or the document has now expired or been replaced.'],
                        ],
                    ],
                    [
                        'title' => 'Control status',
                        'items' => [
                            ['title' => 'State now', 'text' => 'The control state is computed from the requirements that apply and their controls each time the page opens: how many requirements apply, how many are documented, missing or overdue, and whether a mandatory requirement is open. It is not stored.'],
                            ['title' => 'Decision required', 'text' => 'When a mandatory requirement is neither documented nor temporarily accepted, the supplier requires a decision. That is a signal, not a decision. It goes away when the requirement is documented or accepted, or when someone decides «Not approved for new purchases».'],
                            ['title' => 'A person decides', 'text' => 'Approved, Approved with follow-up or Not approved for new purchases is registered by a person with the supplier assurance permission, always with a rationale. Approved requires mandatory and important requirements to be documented; Approved with follow-up requires mandatory requirements to be documented or temporarily accepted.'],
                            ['title' => 'The system never approves by itself', 'text' => 'The system never approves or rejects a supplier automatically, not even when everything is documented. A decision does not change when the state changes later; both are then shown side by side. A new decision is a new row in the history, with the state as it was then.'],
                        ],
                    ],
                    [
                        'title' => 'Follow-up',
                        'items' => [
                            ['title' => 'Upcoming controls', 'text' => 'Procynia calculates when each control requirement should be controlled again: the last control plus the requirement\'s control interval. Requirements without an interval get no fixed date. Documentation used in a control, and temporary acceptance, have dates of their own.'],
                            ['title' => 'Needs attention', 'text' => 'Overdue controls, documents that must be renewed, expired temporary acceptances and requirements not controlled are shown as points needing attention. A requirement is named once; if it requires a decision, it is named there.'],
                            ['title' => 'Nothing happens automatically', 'text' => 'The system never registers a control or a decision when a date passes. An approved supplier stays approved in the history; the state now shows what needs follow-up.'],
                            ['title' => 'Follow up in Deviations and improvements', 'text' => 'A control that is not documented can be followed up as a case in Deviations and improvements. The case does not remove the need for a decision – it is follow-up, not acceptance.'],
                        ],
                    ],
                    [
                        'title' => 'Due diligence and sustainability',
                        'items' => [
                            ['title' => 'What due diligence is', 'text' => 'Mapping, assessing, investigating and following up the risk of breaches of human rights, working conditions and the environment in the supply chain.'],
                            ['title' => 'Six areas, no overall score', 'text' => 'Child labour, forced labour, working conditions, discrimination, freedom of association and environment are assessed one by one: Low, Elevated, High or Unknown. Unknown means it has not been clarified, not that the risk is low. The system does not calculate any overall risk.'],
                            ['title' => 'A person concludes', 'text' => 'You choose the conclusion and give the rationale. The assessment never approves or rejects the supplier, and changes neither the decision nor the criticality.'],
                            ['title' => 'When is it relevant?', 'text' => 'When the profile says the goods are in a high-risk category, that production takes place outside Norway/the EEA, or that the delivery is labour-intensive and uses subcontractors. «Not clarified» counts as the condition applying.'],
                            ['title' => 'Follow up the findings', 'text' => 'With «Measures required» you can follow up in Deviations and improvements. A significant risk to the business can be registered in Risk. A new assessment falls due after the interval you choose.'],
                            ['title' => 'History is not changed', 'text' => 'A due diligence assessment cannot be changed or deleted. Register a new assessment instead.'],
                        ],
                    ],
                    [
                        'title' => 'Supplier assessment',
                        'items' => [
                            ['title' => 'How does the supplier perform?', 'text' => 'Rate quality, delivery precision, information security and compliance, then choose the overall assessment yourself. The system calculates no result.'],
                            ['title' => 'Next review', 'text' => 'The latest assessment plus the supplier\'s review interval. Without an interval or an assessment there is no next date.'],
                            ['title' => 'A mistake in an assessment?', 'text' => 'An assessment cannot be changed or deleted. Register a new assessment instead.'],
                        ],
                    ],
                    [
                        'title' => 'Documentation',
                        'items' => [
                            ['title' => 'What is registered', 'text' => 'Which documentation exists – agreements, data processing agreements, certificates, certificates of insurance and the like – where it is kept, and when it expires. The document itself is not uploaded; it stays where you archive it.'],
                            ['title' => 'Not in the Wiki', 'text' => 'The supplier\'s contracts, certificates and agreements are not put in the Wiki. The Wiki is for knowledge you reuse, not an archive for one supplier\'s documents.'],
                            ['title' => 'Register renewed', 'text' => 'When you receive a new edition, register it as renewed. The previous one stays and is shown as replaced.'],
                            ['title' => 'Used in a control', 'text' => 'Documentation used in a control cannot be deleted. It can still be corrected; the control keeps what was registered. After «Register renewed» you can confirm the requirements again with the new edition.'],
                            ['title' => 'Expired and expiring soon', 'text' => 'Documentation with «Valid until» before today is shown as expired. If it expires within 60 days, the supplier is shown under Needs attention. Without a date it has no expiry date.'],
                        ],
                    ],
                    [
                        'title' => 'Risk',
                        'items' => [
                            ['title' => 'Create risk', 'text' => 'When something can go wrong with the supplier, you create a risk in Risk. You choose the business area and describe the cause, event and consequence. The risk is assessed and treated there.'],
                            ['title' => 'What is shown here', 'text' => 'The supplier page shows the risks that concern the supplier and that you have access to yourself, with business area, status and risk level. Risks you do not have access to are not shown. Criticality does not affect the risk level.'],
                            ['title' => 'Link existing risk', 'text' => 'A risk already registered in Risk can be linked to the supplier. Whoever can edit the risk can remove the link again; the risk stays in Risk.'],
                        ],
                    ],
                    [
                        'title' => 'Requirements',
                        'items' => [
                            ['title' => 'Add requirement', 'text' => 'Requirements that apply to the supplier are added from Compliance and audit. You can choose among active requirements you have access to there. New requirements are registered in Compliance and audit.'],
                            ['title' => 'What is shown here', 'text' => 'The supplier page shows the requirements that apply to the supplier and that you have access to yourself, with reference, title and requirement source. Requirements you do not have access to are not shown.'],
                            ['title' => 'No requirement status here', 'text' => 'That a requirement applies to the supplier does not say whether the supplier meets it. The requirement\'s compliance status in Compliance and audit applies to the organisation, not the supplier. Whether the supplier follows the requirements is judged in the supplier assessment.'],
                        ],
                    ],
                    [
                        'title' => 'Deviations and improvements',
                        'items' => [
                            ['title' => 'Follow up in Deviations and improvements', 'text' => 'When something at the supplier needs follow-up, you create a case in Deviations and improvements. You choose the case type, business area, responsible and deadline. The case is handled there, with actions, status and closing.'],
                            ['title' => 'What is shown here', 'text' => 'The supplier page shows the cases that concern the supplier and that you have access to yourself, with status and deadline. Cases you cannot access are not shown.'],
                            ['title' => 'Link an existing case', 'text' => 'A case already registered in Deviations and improvements can be linked to the supplier. Such a link can be removed again; a case created from here stays linked.'],
                        ],
                    ],
                    [
                        'title' => 'History',
                        'items' => [
                            ['title' => 'What is saved', 'text' => 'Every status change is saved with who made it, when and why. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'End or delete?',
                        'items' => [
                            ['title' => 'End', 'text' => 'The usual way to take a supplier out of use. The history is kept.'],
                            ['title' => 'Delete', 'text' => 'Only for a supplier registered by mistake that has never changed status or criticality, been assessed, had a profile, its own control requirements, controls, decisions or due diligence assessments, had documentation registered or been linked to a case in Deviations and improvements, a risk in Risk or a requirement in Compliance and audit. Deleting cannot be undone.'],
                        ],
                    ],
                ],
            ],
        ],
    ],
    'compliance' => [
        'module_name' => 'Compliance and audit',
        'help' => [
            'button' => 'Help',
            'index' => [
                'title' => 'About requirements',
                'intro' => 'Here you collect the requirements the organisation must comply with – from standards, laws and regulations, contracts and your own internal requirements – with their source, owner and how often they should be reviewed.',
                'sections' => [
                    [
                        'title' => 'Requirements and sources',
                        'items' => [
                            ['title' => 'Requirement', 'text' => 'A requirement is one thing the organisation must meet, for example a control in a standard, a section of a law or an obligation in a contract. It has a title, a requirement text and an owner.'],
                            ['title' => 'Requirement source', 'text' => 'The source is where the requirement comes from: a standard, a law or regulation, a contract, an internal requirement or something else. Sources are managed under Requirement sources on this page. A source can only be deleted when no requirement uses it.'],
                            ['title' => 'Reference', 'text' => 'The requirement\'s number or designation in its source, for example «A.5.1» or «§ 4-2». The reference is optional, but must be unique within the same source.'],
                        ],
                    ],
                    [
                        'title' => 'Compliance and audit',
                        'items' => [
                            ['title' => 'Requirements and compliance', 'text' => 'The requirement says what applies. Whether the organisation meets it is recorded in separate compliance assessments on the requirement page. The Compliance column shows the result of the latest assessment.'],
                            ['title' => 'Requirements and audits', 'text' => 'A requirement says what the organisation must meet. An audit is a planned review in which you check whether the requirements are actually complied with, and record findings.'],
                        ],
                    ],
                    [
                        'title' => 'Compliance',
                        'items' => [
                            ['title' => 'Compliant', 'text' => 'The latest assessment concluded that the organisation meets the requirement.'],
                            ['title' => 'Partially compliant', 'text' => 'The requirement is only partly met. The rationale says what is missing.'],
                            ['title' => 'Non-compliant', 'text' => 'The organisation does not meet the requirement today.'],
                            ['title' => 'Not applicable', 'text' => 'The requirement does not apply to the organisation. This needs a rationale too.'],
                            ['title' => 'Not assessed', 'text' => 'The requirement has no assessment yet. This is not a result anyone chose, but what you see when no assessment exists – which is why it is never stored.'],
                            ['title' => 'Review overdue', 'text' => 'The review interval has passed since the latest assessment. The result still stands, but the requirement should be reassessed. Retired requirements are never overdue.'],
                        ],
                    ],
                    [
                        'title' => 'Needs attention',
                        'items' => [
                            ['title' => 'What it means', 'text' => 'Needs attention means that an active requirement has one or more concrete matters that should be followed up. The list at the top shows which requirements and why, and every requirement in the register shows the same reasons.'],
                            ['title' => 'Not assessed', 'text' => 'The requirement has no compliance assessment yet.'],
                            ['title' => 'Not compliant', 'text' => 'The latest assessment concluded that the requirement is not met.'],
                            ['title' => 'Partially compliant', 'text' => 'The latest assessment concluded that the requirement is only partially met.'],
                            ['title' => 'Review overdue', 'text' => 'The review interval has passed since the latest assessment. The due date itself does not count as overdue.'],
                            ['title' => 'No owner', 'text' => 'Nobody is set as owner of the requirement.'],
                            ['title' => 'Calculated automatically', 'text' => 'The reasons are calculated automatically from the assessments, the review interval and the owner every time the page is opened. They are not statuses of their own, and they never change the requirement or its assessments. Retired requirements never need attention. Once the matter is put right, the reason disappears.'],
                        ],
                    ],
                    [
                        'title' => 'The register',
                        'items' => [
                            ['title' => 'Active', 'text' => 'The requirement applies to the organisation. Active requirements are listed first.'],
                            ['title' => 'Retired', 'text' => 'The requirement no longer applies, for example because the standard has been replaced. It stays in the register with its history.'],
                            ['title' => 'Search and filter', 'text' => 'Search the reference, title and requirement text, and filter by source and status. The filter «Only requirements that need attention» shows the requirements with at least one reason.'],
                        ],
                    ],
                ],
            ],
            'requirement' => [
                'title' => 'About the requirement',
                'intro' => 'The requirement page shows what the requirement says, where it comes from and who follows it up, how the organisation meets it, whether it is met, and how its status has changed.',
                'sections' => [
                    [
                        'title' => 'Ownership and follow-up',
                        'items' => [
                            ['title' => 'Owner', 'text' => 'The person who follows up the requirement. Only active people with access to Compliance and audit can be chosen. Being the owner grants no extra access.'],
                            ['title' => 'No owner', 'text' => 'Shown when the owner has been deleted. Edit the requirement and choose a new owner.'],
                            ['title' => 'Review interval', 'text' => 'How often the requirement should be reassessed: monthly, quarterly, every six months or yearly – or with no fixed interval.'],
                        ],
                    ],
                    [
                        'title' => 'How the requirement is met',
                        'items' => [
                            ['title' => 'Why link processes and controls', 'text' => 'The links show how the organisation intends to meet the requirement: which processes it is followed up in, and which controls are meant to ensure it happens. This makes it easier to assess compliance and to find the supporting material during an audit.'],
                            ['title' => 'Quality owns the processes and controls', 'text' => 'Processes and controls are created and changed in Quality. Only the link is stored here. Name, method, frequency and status are read from Quality every time the page is shown, and removing a link changes nothing in Quality.'],
                            ['title' => 'Evidence is only shown', 'text' => 'The evidence recorded on a control in Quality is shown here as it is. It cannot be added, changed or removed from the requirement page.'],
                            ['title' => 'Evidence is not an assessment', 'text' => 'A control having evidence does not automatically mean the requirement is met, and missing evidence does not automatically mean it is not. Compliance must still be assessed explicitly under Compliance.'],
                            ['title' => 'Retired controls', 'text' => 'A control retired in Quality cannot be linked to new requirements. If it is already linked, the link stays and the control is marked as retired.'],
                            ['title' => 'Access', 'text' => 'You see processes, controls and evidence only if you also have access to Quality. Access to Compliance and audit gives no insight into Quality. Linking takes both the «Register and change requirements and requirement sources» permission and access to Quality, and the requirement must be active.'],
                        ],
                    ],
                    [
                        'title' => 'Compliance',
                        'items' => [
                            ['title' => 'Compliance assessment', 'text' => 'A judgement of whether the organisation meets the requirement now, with a result and a rationale: Compliant, Partially compliant, Non-compliant or Not applicable. The latest assessment is the requirement\'s compliance today. Only active requirements can be assessed, and it takes the «Assess compliance» permission.'],
                            ['title' => 'Not assessed', 'text' => 'Shown when the requirement has never been assessed. It is not a stored result, only the absence of an assessment.'],
                            ['title' => 'Assessments cannot be changed', 'text' => 'An assessment is kept with its date, assessor and rationale, and can be neither changed nor deleted. If an assessment is wrong, you correct it by registering a new one. The date is set by the system.'],
                            ['title' => 'Review interval', 'text' => 'The next assessment is due on the date of the latest assessment plus the interval. From the day after, «Review overdue» is shown. Without an interval there is no fixed next assessment.'],
                            ['title' => 'Requirement changed', 'text' => 'Every assessment keeps the requirement as it was: reference, title, requirement text and source. If the requirement changes afterwards, you are told. The assessment stands, but the requirement should be reassessed.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Active', 'text' => 'The requirement applies and can be edited.'],
                            ['title' => 'Retired', 'text' => 'The requirement no longer applies. It cannot be edited until it is reopened. A reason is required.'],
                            ['title' => 'Reopen', 'text' => 'Makes a retired requirement active again. A reason is required.'],
                        ],
                    ],
                    [
                        'title' => 'Status history',
                        'items' => [
                            ['title' => 'Status history', 'text' => 'Every time the requirement is retired or reopened, who did it, when and why is kept. The history cannot be changed or deleted, and a requirement with history cannot be deleted.'],
                        ],
                    ],
                ],
            ],
            'audit_index' => [
                'title' => 'About audits',
                'intro' => 'Plan and follow up audits here – planned reviews of whether the organisation actually complies with the requirements it has set itself or is subject to.',
                'sections' => [
                    [
                        'title' => 'What an audit is',
                        'items' => [
                            ['title' => 'Audit', 'text' => 'An audit is a planned, bounded review in which you check whether the organisation complies with its requirements in practice. It has a responsible person, a planned period, a scope and finally a conclusion.'],
                            ['title' => 'Internal', 'text' => 'An internal audit is carried out by the organisation itself, for example by an internal auditor or quality manager.'],
                            ['title' => 'External', 'text' => 'An external audit is carried out by someone outside the organisation, for example a certification body, a customer or a regulator. The name of the auditor or audit firm can be entered in the Auditor field.'],
                            ['title' => 'Responsible', 'text' => 'The person in the organisation who is responsible for the audit, also when it is carried out by an external auditor. Only active people with access to Compliance and audit can be chosen.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Planned', 'text' => 'The audit is registered but not started. Everything can still be changed.'],
                            ['title' => 'In progress', 'text' => 'The audit has started. Scope, responsible person, auditor and conclusion can still be changed.'],
                            ['title' => 'Completed', 'text' => 'The audit has ended with a conclusion. It is locked and can only be changed after it has been reopened.'],
                            ['title' => 'Cancelled', 'text' => 'The audit was not carried out. It stays in the register with its reason, but cannot be changed.'],
                        ],
                    ],
                    [
                        'title' => 'Needs attention',
                        'items' => [
                            ['title' => 'What it means', 'text' => 'Needs attention means that an audit has something concrete that should be followed up. The list at the top shows which audits and why, and every audit in the register shows the same reasons.'],
                            ['title' => 'Audit overdue', 'text' => 'The audit is planned or in progress, and the planned end has passed. The end date itself does not count as overdue.'],
                            ['title' => 'Nonconformity not followed up', 'text' => 'The audit is completed, and at least one nonconformity has not been followed up in Deviations & improvements. Observations and improvement opportunities do not count.'],
                            ['title' => 'Calculated automatically', 'text' => 'The reasons are calculated automatically from the status, the planned end and the findings every time the page is opened. They are not statuses of their own. Once the nonconformity is followed up or the audit is completed, the reason disappears. Cancelled audits never need attention.'],
                        ],
                    ],
                    [
                        'title' => 'The register',
                        'items' => [
                            ['title' => 'Search and filter', 'text' => 'Search in title, scope and auditor, and filter by status and type. Audits in progress are shown first, then planned, completed and cancelled ones.'],
                            ['title' => 'Findings', 'text' => 'Audit findings – nonconformities, observations and improvement opportunities – are recorded on the audit page while the audit is in progress. Follow-up happens in Deviations & improvements.'],
                        ],
                    ],
                ],
            ],
            'audit' => [
                'title' => 'About the audit',
                'intro' => 'The audit page shows what the audit covers, which requirements and processes it looks at, the conclusion and how its status has changed.',
                'sections' => [
                    [
                        'title' => 'Scope',
                        'items' => [
                            ['title' => 'Scope', 'text' => 'The scope describes what the audit covers and is limited to, for example «Internal audit of access control and user administration for the IT department». The description is required and is what applies.'],
                            ['title' => 'Requirements in scope', 'text' => 'The requirements the audit will check. The link makes it easy to see which requirements were audited, and to go to the requirement and its assessments. Requirements are added as fixed rows: requirements added later are not included by themselves.'],
                            ['title' => 'From requirement source', 'text' => 'Add all active requirements from a requirement source in one step. This is only a shortcut – the requirements are added one by one and can be removed again.'],
                            ['title' => 'Retired', 'text' => 'A retired requirement can be in scope, for example when the audit looks at what used to apply. It is marked as retired and is not removed automatically.'],
                            ['title' => 'Processes in scope', 'text' => 'The processes in Quality that the audit looks at. The processes are owned by Quality; only the link is stored here. You see and link processes only if you also have access to Quality.'],
                        ],
                    ],
                    [
                        'title' => 'Findings',
                        'items' => [
                            ['title' => 'Findings', 'text' => 'A finding is something the audit found. It is recorded while the audit is in progress, with a type, title, description and optionally the requirement, process and control it concerns.'],
                            ['title' => 'Nonconformity', 'text' => 'A requirement is not met. A nonconformity should be followed up in Deviations & improvements.'],
                            ['title' => 'Observation', 'text' => 'Something worth noting, but not a breach of a requirement. It may, for example, become a nonconformity if it is not followed up.'],
                            ['title' => 'Improvement opportunity', 'text' => 'Something works, but could be better.'],
                            ['title' => 'Findings are not actions', 'text' => 'A finding has no owner, due date, status or actions. Follow-up – responsibility, actions, due dates and closing – happens in Deviations & improvements.'],
                            ['title' => 'Follow up in Deviations & improvements', 'text' => 'Creates a new case from the finding. It only happens when someone chooses it – never automatically. You choose the business area, owner and due date; the title and description are taken from the finding. A nonconformity becomes a deviation, observations and improvement opportunities an improvement. It can also be done after the audit is completed.'],
                            ['title' => 'Handed off', 'text' => 'A handed-off finding is locked for good, also if the audit is reopened, and cannot be deleted. The audit only shows that the finding was handed off – not the case\'s status, actions or due dates.'],
                            ['title' => 'What you have no access to', 'text' => 'Process and control are shown only if you have access to Quality. A case in a business area you do not have access to is shown only as «Handed off» – without link and title.'],
                        ],
                    ],
                    [
                        'title' => 'Carrying it out',
                        'items' => [
                            ['title' => 'Start audit', 'text' => 'Moves the audit from Planned to In progress. The type cannot be changed once the audit has started.'],
                            ['title' => 'Conclusion', 'text' => 'The overall assessment of the audit. It is written while the audit is in progress, and must be filled in before the audit can be completed.'],
                            ['title' => 'Complete audit', 'text' => 'Ends the audit with the conclusion. An audit can be completed without findings. Afterwards it is locked, but findings not yet handed off can still be followed up.'],
                            ['title' => 'Needs attention', 'text' => 'Shown under the title when the audit has passed its planned end without being completed, or is completed with nonconformities that have not been followed up. Calculated automatically and not stored.'],
                            ['title' => 'Cancel audit', 'text' => 'Used when the audit will not be carried out after all. A reason is required, and the audit stays as cancelled.'],
                            ['title' => 'Reopen audit', 'text' => 'Makes a completed audit editable again, for example to correct the conclusion. A reason is required, and the reopening is logged.'],
                        ],
                    ],
                    [
                        'title' => 'Status history',
                        'items' => [
                            ['title' => 'Status history', 'text' => 'Every status change is stored with who made it, when and any reason. The history cannot be changed or deleted, and an audit with history cannot be deleted – it is cancelled instead.'],
                        ],
                    ],
                ],
            ],
