    'improvements' => [
        'help' => [
            'button' => 'Help',
            'index' => [
                'title' => 'About Deviations & improvements',
                'intro' => 'Here you register and follow up on things that are not as they should be, and ideas for how something can get better. Each case has an owner and is followed from registration until it is closed.',
                'sections' => [
                    [
                        'title' => 'Deviation or improvement',
                        'items' => [
                            ['title' => 'Deviation', 'text' => 'Something is not as intended, for example an error, an incident or a procedure that was not followed. Describe what happened and what was expected.'],
                            ['title' => 'Improvement', 'text' => 'Something could be better, even if nothing has gone wrong. Describe what can be improved and why it would be useful.'],
                            ['title' => 'What should I register?', 'text' => 'Register the case as soon as you notice it. A title, a description, a business area and an owner are enough. You do not need to know the cause or what should be done to register the case.'],
                        ],
                    ],
                    [
                        'title' => 'The case',
                        'items' => [
                            ['title' => 'Business area', 'text' => 'Each case belongs to one business area. The business area decides who can see and handle the case. You only see the cases in the business areas your roles give you.'],
                            ['title' => 'Owner', 'text' => 'The person who follows up the case until it is closed. Only people who can see cases in the business area can be chosen.'],
                            ['title' => 'Status', 'text' => 'Open: registered but not started. In progress: someone is working on the case. Closed: handled. Cancelled: will not be handled further.'],
                            ['title' => 'Due date', 'text' => 'When the case should be handled. The due date is optional. If it has passed while the case is still open or in progress, the overview says «Overdue».'],
                            ['title' => 'Date of occurrence', 'text' => 'For deviations: the date it happened. The field is optional and is not shown for improvements.'],
                            ['title' => 'Actions in the overview', 'text' => 'For cases with actions, the overview shows how many actions the case has, and how many of them are open – that is, planned or in progress.'],
                        ],
                    ],
                    [
                        'title' => 'Needs attention',
                        'items' => [
                            ['title' => 'What is shown here?', 'text' => 'Cases and actions waiting for someone to act. Only cases that are open or in progress are included, and only in the business areas you have access to. Choose «Show» to see which cases and actions it concerns, and why.'],
                            ['title' => 'Case past due date', 'text' => 'The case\'s due date has passed. Handle the case, or set a new due date if the old one is no longer right.'],
                            ['title' => 'Action past due date', 'text' => 'An action that is planned or in progress has passed its due date. Complete the action, or agree a new due date with the owner.'],
                            ['title' => 'Case without owner', 'text' => 'The case has no owner, for example because the person is no longer a user. Choose a new owner.'],
                            ['title' => 'Action without owner', 'text' => 'An action that is not finished has no owner. Choose a new owner on the action.'],
                            ['title' => 'Awaiting effectiveness check', 'text' => 'The action is completed, but nobody has judged whether it worked. Check the effect when you have grounds to judge it.'],
                            ['title' => 'Action not effective', 'text' => 'The latest judgement says the action did not work. Reopen the action and keep working on it. If a new action is to replace it, reopen and cancel the old one.'],
                            ['title' => 'How it is counted', 'text' => 'Cases and actions are counted separately. A case or an action with several findings is counted only once.'],
                        ],
                    ],
                ],
            ],
            'case' => [
                'title' => 'About the case',
                'intro' => 'The case page brings together what the case is about, who owns it, how far the handling has come and what has been done.',
                'sections' => [
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Open', 'text' => 'The case is registered, but handling has not started. Choose «Start handling» when the work begins.'],
                            ['title' => 'In progress', 'text' => 'Someone is working on the case. It can still be edited.'],
                            ['title' => 'Closed', 'text' => 'The case has been handled. The result is shown on the page and in the history.'],
                            ['title' => 'Cancelled', 'text' => 'The case will not be handled further, for example because it is a duplicate or was registered by mistake. The reason is shown on the page and in the history.'],
                        ],
                    ],
                    [
                        'title' => 'Cause and background',
                        'items' => [
                            ['title' => 'What do I write here?', 'text' => 'For a deviation: why it happened, if you know. For an improvement: the background for the improvement and what should change. The field is optional and can be filled in when you know more.'],
                            ['title' => 'When can it be changed?', 'text' => 'While the case is open or in progress. A closed or cancelled case must be reopened first.'],
                        ],
                    ],
                    [
                        'title' => 'Actions',
                        'items' => [
                            ['title' => 'What is an action?', 'text' => 'A concrete activity to be carried out to correct the deviation or make the improvement. A case can have several actions.'],
                            ['title' => 'Owner and due date', 'text' => 'Each action has one owner and a due date. Only people who can see cases in the case\'s area can be chosen. If the due date has passed while the action is not done, it says «Overdue».'],
                            ['title' => 'Start action', 'text' => 'Choose «Start action» when the work begins. The action gets the status In progress.'],
                            ['title' => 'Complete action', 'text' => 'When the action has been carried out, choose «Complete action» and write briefly in the field «What was done?». The text, the date and who completed it are shown on the action.'],
                            ['title' => 'Cancel action', 'text' => 'Use this when the action will not be carried out. Write a reason so that others can see why.'],
                            ['title' => 'Reopen action', 'text' => 'A completed or cancelled action can be reopened with a reason. It becomes planned again, and the earlier completion or cancellation stays in the history.'],
                            ['title' => 'Action history', 'text' => 'Each action has its own history with the date, who made the change and the comment. The history cannot be changed or deleted.'],
                            ['title' => 'Actions and ending the case', 'text' => 'A case with actions that are planned or in progress can be neither closed nor cancelled. Complete or cancel the actions first. A case that has actions cannot be deleted either.'],
                            ['title' => 'Delete action', 'text' => 'An action added by mistake can be deleted as long as it is planned and has never been started, completed or cancelled.'],
