                            ['title' => 'Result / closing comment', 'text' => 'Write briefly what was done, or why the case can be closed. The text is required, and is shown on the case and in the history.'],
                            ['title' => 'Cancel case', 'text' => 'Use this when the case will not be handled further. Write a reason so that others can see why. Actions that are planned or in progress must be completed or cancelled first, but completed actions need no effectiveness check.'],
