        'ask_page_help_item_not_bid_answer_text' => 'Ask Wiki gives short, direct answers about your own documented knowledge. It does not write bid text and is not linked to a case. Use the AI module when drafting an answer to a specific requirement.',
        'ask_page_help_item_single_question_title' => 'One question at a time',
        'ask_page_help_item_single_question_text' => 'This first version answers one question at a time, with no conversation history. Ask a new, more specific question if the answer missed the mark.',
        'index_title' => 'Wiki',
        'index_description' => 'Structured knowledge about the company, generated from approved content.',
        'page_help_button' => 'Help',
        'page_help_title' => 'How Wiki pages work',
        'page_help_intro' => 'Wiki pages are built from the company’s source documents. Document Owners, source basis, approvals, and quality control keep the content grounded in the business and preserve traceability.',
        'show_page_help_title' => 'How this Wiki page works',
        'show_page_help_intro' => 'Explains what you are looking at on this Wiki page: what is published, what is being worked on, who is responsible, and what happens when you send the page on.',

        'show_page_help_section_about' => 'About this page',
        'show_page_help_item_about_title' => 'One Wiki page, two versions',
        'show_page_help_item_about_text' => 'This page shows the content being worked on, who is responsible for the review, and which version — if any — is already published.',
        'show_page_help_item_ai_title' => '"AI-generated" is not a status',
        'show_page_help_item_ai_text' => 'The AI-generated draft notice appears on every page that has not been through review, because the content is built by Procynia from the source documents. It says where the content came from, not how far the page has got.',
        'show_page_help_item_type_title' => '"Concept" is a page type, not a status',
        'show_page_help_item_type_text' => 'Concept, Article, Summary and Entity describe what kind of page this is. The page type does not change when the page is approved.',
        'show_page_help_item_visibility_title' => 'Status does not hide the page',
        'show_page_help_item_visibility_text' => 'Every authorised Wiki user at the customer can read the page whatever its status. Status only governs who can act on it.',

        'show_page_help_section_versions' => 'Published and working version',
        'show_page_help_item_published_title' => 'The published version is the one that counts',
        'show_page_help_item_published_text' => 'Once a version is approved it becomes the published knowledge on the page. That is what users and AI answers build on. Quality assurance can still be under way.',
        'show_page_help_item_working_title' => 'The working version changes nothing until it is approved',
        'show_page_help_item_working_text' => 'A newer working version can be under editing or review while the previously published version is still the approved knowledge. Only when the working version is approved does it replace the previous one. Earlier versions are kept.',

        'show_page_help_section_responsibility' => 'Responsibility and review',
        'show_page_help_item_owner_title' => 'Page owner',
        'show_page_help_item_owner_text' => 'Responsible for the Wiki page, corrects the draft and sends it for review.',
        'show_page_help_item_reviewer_title' => 'Reviewer',
        'show_page_help_item_reviewer_text' => 'The reviewer carries out the final review: approves and publishes the page, or sends it back with a comment. A page is always published by somebody other than the person who sent it in.',
        'show_page_help_item_submit_title' => 'Send for review',
        'show_page_help_item_submit_text' => 'The page owner picks a named reviewer, who is notified and gets the task under Follow-up. The reviewer cannot be the person who sends it in.',
        'show_page_help_item_publish_title' => 'Approve and publish',
        'show_page_help_item_publish_text' => 'The working version becomes the published knowledge on the page. Nothing else has to be finished first.',
        'show_page_help_item_edit_title' => 'Edit article',
        'show_page_help_item_edit_text' => 'Changes the working version. The published version is untouched until the new one is approved.',

        'show_page_help_section_quality' => 'Quality assurance',
        'show_page_help_item_quality_who_title' => 'Quality reviewer',
        'show_page_help_item_quality_who_text' => 'Checks the individual claims in the content against the sources. The page owner can assign one at any time, on pages that have claims.',
        'show_page_help_item_quality_optional_title' => 'Support for the work, not a condition for publishing',
        'show_page_help_item_quality_optional_text' => 'Quality assurance stops nothing. A page can be published with no claims quality assured, and the work can continue afterwards. "0 of 9 claims quality assured" therefore says something about the quality work, not about publication.',

        'show_page_help_section_sources' => 'Source material',
        'show_page_help_item_document_owner_title' => 'Document owner',
        'show_page_help_item_document_owner_text' => 'Recorded as responsible for the source document, and can confirm or object to how the content is represented. This is traceability: the Wiki page can be published whether or not they have taken a view.',

        'show_page_help_section_changes' => 'Changes requested',
        'show_page_help_item_changes_who_title' => 'Both the reviewer and a document owner can request changes',
        'show_page_help_item_changes_who_text' => 'The page goes back to the page owner for correction. The published version is untouched — it keeps applying.',
        'show_page_help_item_changes_reason_title' => 'The reason comes with it',
        'show_page_help_item_changes_reason_text' => 'Whoever requests changes must write what needs correcting. The reason is shown on the page, and earlier feedback is kept.',
        'show_page_help_item_changes_resubmit_title' => 'Correct it and send it again',
        'show_page_help_item_changes_resubmit_text' => 'The page owner reopens the page, corrects the content and sends it for review again. A reviewer is chosen afresh for each round.',

        'show_page_help_submit_hint_label' => 'Show explanation for Send for review',
        'show_page_help_submit_hint' => 'You pick a reviewer, who is notified. Document owners can comment on content from their sources, but the reviewer is the one who publishes.',

        'show_page_help_section_best_practice' => 'Best-practice suggestion',
        'show_page_help_item_best_practice_what_title' => 'A suggestion, not an error',
        'show_page_help_item_best_practice_what_text' => 'Best-practice text is a deliberate suggestion beyond the source document, not documented customer knowledge. It is not a technical error, and it does not block quality control.',
        'show_page_help_item_best_practice_decide_title' => 'Approve, edit, or reject',
        'show_page_help_item_best_practice_decide_text' => 'You can approve the suggestion as-is, edit the text and approve it, or reject it. The decision applies to the specific text it was suggested for.',
        'show_page_help_item_best_practice_defect_title' => 'Undocumented factual claims are different',
        'show_page_help_item_best_practice_defect_text' => 'Text presented as an actual fact about the customer, but not supported by the source and not classified as best practice either, is still treated as a quality defect.',
        'show_page_help_section_blocking' => 'Severity and blocking',
        'show_page_help_item_blocking_categories_title' => 'Every finding gets a concrete explanation',
        'show_page_help_item_blocking_categories_text' => 'Findings are no longer shown with one generic default message. Every finding shows the specific claim, what the system thinks deviates, and why.',
        'show_page_help_item_blocking_technical_title' => 'A technical uncertainty is not the same as a content error',
        'show_page_help_item_blocking_technical_text' => 'When the system could not find a confident link between a claim and a source paragraph, this is shown as a technical uncertainty — not as a confirmed content error. Such findings usually do not block by default.',
        'show_page_help_item_blocking_override_title' => 'You can keep or remove blocking',
        'show_page_help_item_blocking_override_text' => 'The system suggests whether a finding should block, but an authorized user can override this. The decision is stored with the user, timestamp, and any comment.',
        'page_help_section_workflow' => 'The workflow',
        'page_help_item_workflow_source_title' => 'The source document comes first',
        'page_help_item_workflow_source_text' => 'A source document is uploaded and becomes the basis for a new Wiki page.',
        'page_help_item_workflow_owner_title' => 'The Document Owner follows the document',
        'page_help_item_workflow_owner_text' => 'The document gets a Document Owner who is responsible for the source basis. The same person can own multiple documents.',
        'page_help_item_workflow_wiki_title' => 'The Wiki page is built and checked',
        'page_help_item_workflow_wiki_text' => 'Procynia generates Wiki pages and claims, links them to the correct sources, and runs claims, quality control, and QA before the material is used.',
        'page_help_item_workflow_blocked_title' => '"Still processing" means content could not be confirmed',
        'page_help_item_workflow_blocked_text' => 'If the system finds statements not supported by the source material, or an internal generation error, the page is stopped before Document Owner approval. This is resolved technically or through a controlled revision — the Document Owner does not need to do anything until the page is ready.',
        'page_help_section_owner' => 'What is a Document Owner?',
        'page_help_item_owner_definition_title' => 'Subject-matter responsibility for the source document',
        'page_help_item_owner_definition_text' => 'The Document Owner is the person who has subject-matter responsibility for a source document. The Document Owner can be different from the person who uploaded the document.',
        'page_help_item_owner_page_title' => 'Approves the concrete page version',
        'page_help_item_owner_page_text' => 'The Document Owner reviews the specific Wiki page version that is based on the document. Approval does not mean that all material is automatically correct.',
        'page_help_item_owner_scope_title' => 'Document Owner approval is not the same as QA',
        'page_help_item_owner_scope_text' => 'Claim verification checks whether a claim has source support. QA checks quality across the Wiki material. Document Owner approval is the subject-matter review from the person who owns the source document.',
        'page_help_section_multiple' => 'Why can a page have several owners?',
        'page_help_item_multiple_sources_title' => 'One page can be based on several documents',
        'page_help_item_multiple_sources_text' => 'When a Wiki page is based on several source documents, the page gets several Document Owners because each document has its own responsible owner.',
        'page_help_item_multiple_one_title' => 'One owner per document',
        'page_help_item_multiple_one_text' => 'When the same person owns multiple documents that support the same page, that person normally gets one combined approval task. Traceability for each document is still preserved.',
        'page_help_item_multiple_status_title' => 'The combined status shows how far the page has progressed',
        'page_help_item_multiple_status_text' => 'If a page has several owners, some can be approved while others are still pending. The page is not fully owner-approved until every required owner has approved their source basis.',
        'page_help_section_statuses' => 'What do the statuses mean?',
        'page_help_item_status_article_title' => 'Article status and Document Owner status are different',
        'page_help_item_status_article_text' => 'Article status describes the Wiki page itself. Document Owner status describes whether the people responsible for the source documents have approved the material. A page can be Approved as an article and still wait for Document Owner approval.',
        'page_help_item_status_draft_title' => 'Draft',
        'page_help_item_status_draft_text' => 'The page has been created, but it is not finished yet.',
        'page_help_item_status_approved_title' => 'Published',
        'page_help_item_status_approved_text' => 'The page is published and is the version readers and tender drafting get.',
        'page_help_item_status_sync_title' => 'Awaiting sync',
        'page_help_item_status_sync_text' => 'The source document has a Document Owner, but the approval task for the Wiki page has not yet been fully created or updated. This is a technical intermediate state.',
        'page_help_item_status_missing_owner_title' => 'Missing Document Owner',
        'page_help_item_status_missing_owner_text' => 'The page uses at least one source document that does not have a valid, active Document Owner.',
        'page_help_item_status_rejected_title' => 'Rejected',
        'page_help_item_status_rejected_text' => 'At least one required Document Owner has rejected the material. The material cannot be completed until the issue has been addressed.',
        'page_help_item_status_visibility_title' => 'Who can see a page, regardless of status?',
        'page_help_item_status_visibility_text' => 'Any authorized Wiki user at the customer can open and read a page regardless of its status — status only controls who can approve, reject, edit, or publish it. The Wiki graph uses the same rule, so a page is never shown in the graph without also being openable here.',
        'page_help_section_changes' => 'When content or ownership changes',
        'page_help_item_changes_content_title' => 'Material changes can require a new approval',
        'page_help_item_changes_content_text' => 'An approval applies to a specific Wiki page version. If the content changes significantly, the page may need a new review.',
        'page_help_item_changes_owner_title' => 'New source basis can create new approval tasks',
        'page_help_item_changes_owner_text' => 'If a document gets a new owner or new content, the system updates who should approve the pages that actually use that document.',
        'page_help_item_changes_history_title' => 'History is kept',
        'page_help_item_changes_history_text' => 'Earlier approvals are not deleted. Older decisions should remain visible as history.',
        'page_help_section_actions' => 'What should you do?',
        'page_help_item_actions_sources_title' => 'Check the source documents first',
        'page_help_item_actions_sources_text' => 'Go to Source documents, make sure each document has the right Document Owner, and fix documents that are missing an owner.',
        'page_help_item_actions_pages_title' => 'Use Wiki pages to approve the material',
        'page_help_item_actions_pages_text' => 'Open Wiki pages, review the content and sources, and choose Approve or Reject when you assess the material based on the document.',
        'page_help_item_actions_qa_title' => 'Let QA and Document Owner do different jobs',
        'page_help_item_actions_qa_text' => 'QA checks quality across the Wiki material. Document Owner approval confirms that the material is grounded in the relevant source basis. One does not replace the other.',
        'sources_page_help_title' => 'How source documents work',
        'sources_page_help_intro' => 'Source documents are the foundation for Enterprise Wiki. Here you upload documents, choose a Document Owner, follow the processing, and see which Wiki pages use the document.',
        'sources_page_help_section_what' => 'What are source documents?',
        'sources_page_help_item_what_title' => 'Grounding for Wiki content',
        'sources_page_help_item_what_text' => 'Source documents are the documents Procynia uses as the factual basis for Wiki pages, claims, and source references. The document remains a traceable source and is not automatically put to use just because it was uploaded.',
        'sources_page_help_item_what_ai_title' => 'The text is extracted and analyzed',
        'sources_page_help_item_what_ai_text' => 'When a document is uploaded, Procynia reads the text, analyzes the content, and makes it ready for further Wiki processing. Only material that actually uses the document gets it as a source.',
        'sources_page_help_section_workflow' => 'The workflow',
        'sources_page_help_item_workflow_upload_title' => 'Upload the document',
        'sources_page_help_item_workflow_upload_text' => 'You upload a source document and choose a Document Owner if you have permission to do so.',
        'sources_page_help_item_workflow_process_title' => 'The document is processed first',
        'sources_page_help_item_workflow_process_text' => 'Procynia extracts and analyzes the document before it can be used as a basis for new Wiki pages.',
        'sources_page_help_item_workflow_wiki_title' => 'Then Wiki material can be generated',
        'sources_page_help_item_workflow_wiki_text' => 'When the document is ready, you can start a Wiki draft. The generated pages are linked to the actual sources and continue through claims, quality control, QA and Document Owner approval.',
        'sources_page_help_section_owner' => 'Document Owner',
        'sources_page_help_item_owner_definition_title' => 'Factual responsibility for the document',
        'sources_page_help_item_owner_definition_text' => 'The Document Owner is the person with factual responsibility for the source document. The Document Owner can be someone other than the person who uploaded the document.',
        'sources_page_help_item_owner_scope_title' => 'One owner per document',
        'sources_page_help_item_owner_scope_text' => 'One source document has one Document Owner. One person can own several documents, and only active and qualified users in the same customer environment can be selected.',
        'sources_page_help_item_owner_approval_title' => 'Ownership is not approval',
        'sources_page_help_item_owner_approval_text' => 'Choosing a Document Owner does not approve the Wiki material automatically. The Document Owner must later review the specific Wiki page version that is based on the document.',
        'sources_page_help_section_columns' => 'The columns in the list',
        'sources_page_help_item_columns_filename_title' => 'File name',
        'sources_page_help_item_columns_filename_text' => 'The name of the uploaded source document.',
        'sources_page_help_item_columns_status_title' => 'Status',
        'sources_page_help_item_columns_status_text' => 'Shows how far the document processing has come, for example Processing, Extracted, or Failed.',
