        'sources_page_help_item_columns_actions_title' => 'Actions',
        'sources_page_help_item_columns_actions_text' => 'Here you will find actions such as creating a Wiki draft, opening runs, viewing the original document, or deleting the document.',
        'sources_page_help_section_statuses' => 'What do the statuses mean?',
        'sources_page_help_item_status_uploaded_title' => 'Uploaded',
        'sources_page_help_item_status_uploaded_text' => 'The document has been received, but processing is not finished.',
        'sources_page_help_item_status_processing_title' => 'Processing',
        'sources_page_help_item_status_processing_text' => 'Procynia is extracting or analyzing the content.',
        'sources_page_help_item_status_extracted_title' => 'Extracted',
        'sources_page_help_item_status_extracted_text' => 'The text has been extracted, and the document is ready for further Wiki processing.',
        'sources_page_help_item_status_completed_title' => 'Completed',
        'sources_page_help_item_status_completed_text' => 'The current processing step is finished.',
        'sources_page_help_item_status_failed_title' => 'Failed',
        'sources_page_help_item_status_failed_text' => 'Processing stopped because of an error. Open the run details for a clear explanation and possible next step.',
        'sources_page_help_section_changes' => 'When the document changes',
        'sources_page_help_item_changes_owner_title' => 'A new owner creates new tasks',
        'sources_page_help_item_changes_owner_text' => 'When the Document Owner changes, the record of who is responsible for the Wiki pages that actually use the document is updated. History is kept.',
        'sources_page_help_item_changes_delete_title' => 'Deletion shows the consequences first',
        'sources_page_help_item_changes_delete_text' => 'Before you delete a document, Procynia shows which Wiki pages, claims and saved Wiki answers may be affected. A document can be one of several sources, so not all material necessarily disappears.',
        'sources_page_help_item_delete_full_title' => '"Delete document and generated Wiki content"',
        'sources_page_help_item_delete_full_text' => 'This action deletes the source document and all Enterprise Wiki content that is only generated from it — page versions, runs, claims, source references and findings. Wiki pages that are also built from other source documents are not deleted, only this document\'s link to them is removed. This action cannot be undone. The document cannot be deleted while a Wiki run is in progress for it. Deletion does not affect the customer, other users, or other documents.',
        'sources_page_help_section_actions' => 'What should you do?',
        'sources_page_help_item_actions_upload_title' => 'For a new document',
        'sources_page_help_item_actions_upload_text' => 'Upload the document, choose the right Document Owner, and follow the processing under Runs until it is ready for Wiki generation.',
        'sources_page_help_item_actions_fail_title' => 'When processing fails',
        'sources_page_help_item_actions_fail_text' => 'Open the run, read the understandable error text, and check the document format and content before trying again.',
        'sources_page_help_item_actions_delete_title' => 'When the document should be deleted',
        'sources_page_help_item_actions_delete_text' => 'Read the impact analysis carefully and check which Wiki pages and answers are affected before you confirm the deletion.',
        'runs_page_help_title' => 'How runs work',
        'runs_page_help_intro' => 'Runs show how source documents are processed and become Wiki material. Here you can follow progress, see which step the processing is on, and find understandable explanations when something stops or waits for approval.',
        'runs_page_help_section_what' => 'What is a processing run?',
        'runs_page_help_item_what_title' => 'One coordinated process',
        'runs_page_help_item_what_text' => 'A processing run is one coordinated process that handles one or more source documents and builds or updates Enterprise Wiki material. A run is created when Wiki processing starts, and each run has its own status and progress.',
        'runs_page_help_item_what_separate_title' => 'Separate from ordinary answer drafts',
        'runs_page_help_item_what_separate_text' => 'Runs are separate from the normal answer engine and ordinary answer drafts. They produce Wiki material, claims and control basis, not regular requirement answers.',
        'runs_page_help_section_when' => 'When is a run created?',
        'runs_page_help_item_when_start_title' => 'When Wiki processing starts',
        'runs_page_help_item_when_start_text' => 'A run can be created when the user chooses Create Wiki for a source document, or when existing Wiki material must be reprocessed or restored through the existing UI.',
        'runs_page_help_item_when_scope_title' => 'One run can cover more than one step',
        'runs_page_help_item_when_scope_text' => 'A run can be tied to one specific document or to a larger Wiki processing flow. Which steps are shown depends on the type of processing the run performs.',
        'runs_page_help_section_progress' => 'How to read the progress',
        'runs_page_help_item_progress_status_title' => 'Status',
        'runs_page_help_item_progress_status_text' => 'Status shows the overall state of the run, for example Waiting, Processing, Generating Wiki pages, Awaiting QA, Completed or Failed.',
        'runs_page_help_item_progress_activity_title' => 'Activity',
        'runs_page_help_item_progress_activity_text' => 'Activity shows what the run is working on right now. It is more useful than status alone while the processing is active.',
        'runs_page_help_item_progress_bar_title' => 'Progress and last progress',
        'runs_page_help_item_progress_bar_text' => 'Progress shows how much of the known processing is complete. Last progress shows when the run last reported actual progress.',
        'runs_page_help_section_statuses' => 'What do the statuses mean?',
        'runs_page_help_item_status_queued_title' => 'Pending',
        'runs_page_help_item_status_queued_text' => 'The run has been created, but the processing has not started yet.',
        'runs_page_help_item_status_running_title' => 'Processing',
        'runs_page_help_item_status_running_text' => 'Procynia is actively working on the run.',
        'runs_page_help_item_status_pages_title' => 'Generating Wiki pages',
        'runs_page_help_item_status_pages_text' => 'Wiki pages or page versions are being built from the source documents.',
        'runs_page_help_item_status_verify_title' => 'Checking claims',
        'runs_page_help_item_status_verify_text' => 'Claims and source basis are verified, and links and relations are built.',
        'runs_page_help_item_status_qa_title' => 'Quality control',
        'runs_page_help_item_status_qa_text' => 'The system checks structure, coverage, source basis and other quality requirements.',
        'runs_page_help_item_status_missing_owner_title' => 'Missing Document Owner',
        'runs_page_help_item_status_missing_owner_text' => 'A used source document does not have a valid, active Document Owner.',
        'runs_page_help_item_status_completed_title' => 'Completed',
        'runs_page_help_item_status_completed_text' => 'All required processing steps and completion gates are finished.',
        'runs_page_help_item_status_failed_title' => 'Failed',
        'runs_page_help_item_status_failed_text' => 'Processing stopped because of an error. The error message should describe the problem in plain language, without requiring internal job or exception names.',
        'runs_page_help_item_status_escalated_title' => 'Escalated',
        'runs_page_help_item_status_escalated_text' => 'Something required extra follow-up, and the run needs further handling before it can be considered finished.',
        'runs_page_help_item_status_decision_only_title' => 'Decision saved',
        'runs_page_help_item_status_decision_only_text' => 'The run was used to record a decision without starting the full processing flow.',
        'runs_page_help_item_status_cancelled_title' => 'Cancelled',
        'runs_page_help_item_status_cancelled_text' => 'The run was manually cancelled by a user, usually to make the source document deletable. Wiki content already generated is kept.',
        'runs_page_help_section_pages' => 'Affected Wiki pages',
        'runs_page_help_item_pages_what_title' => 'Pages shows affected Wiki pages',
        'runs_page_help_item_pages_what_text' => '"Pages" shows how many Wiki pages the document created or updated. Click the number to see which pages are affected, without leaving the run list.',
        'runs_page_help_item_pages_created_updated_title' => 'Created and Updated',
        'runs_page_help_item_pages_created_updated_text' => '"Created" means the run made a brand new Wiki page. "Updated" means a page that already existed got a new version.',
        'runs_page_help_item_pages_owner_status_title' => 'Document Owner status',
        'runs_page_help_item_pages_owner_status_text' => 'Document Owner status is shown per page version — the version the run actually produced. The list shows which page or action remains before the run can be considered finished.',
        'runs_page_help_item_pages_stalled_title' => '"Seems stalled"',
        'runs_page_help_item_pages_stalled_text' => '"Seems stalled" means no new progress has been recorded for a while. It does not necessarily mean something has failed — the run may be waiting for an action, such as a Document Owner approval.',
        'runs_page_help_section_findings' => 'Quality findings',
        'runs_page_help_item_findings_what_title' => 'Findings shows all quality findings',
        'runs_page_help_item_findings_what_text' => '"Findings" shows every quality finding recorded during the run. Click the number to see what the findings are about.',
        'runs_page_help_item_findings_not_error_title' => 'Not necessarily an error',
        'runs_page_help_item_findings_not_error_text' => 'A finding is not necessarily an error that blocks. Findings can be open, resolved, accepted, or informative, and a run can pass even when historical or non-blocking findings exist.',
        'runs_page_help_item_findings_action_title' => 'What needs action?',
        'runs_page_help_item_findings_action_text' => 'The panel shows which findings actually need action, and which page and page version the finding applies to when that is known.',
        'runs_page_help_item_findings_best_practice_title' => 'Best-practice suggestion',
        'runs_page_help_item_findings_best_practice_text' => 'Best-practice text is a suggestion, not an error. It does not come directly from the customer\'s source document, and it does not block technical QA. Click Open and review to go directly to the text and approve, edit, or reject it. Genuine undocumented factual claims are still treated as quality defects.',
        'runs_page_help_section_workflow' => 'Active processing or waiting on a person?',
        'runs_page_help_item_workflow_active_title' => 'Active processing',
        'runs_page_help_item_workflow_active_text' => 'Procynia works on analysis, generation, claims, links, source checking and quality control. While a run is active, Procynia updates the view automatically so new progress is visible without manually reloading the page.',
        'runs_page_help_item_workflow_waiting_title' => 'Waiting for human action',
        'runs_page_help_item_workflow_waiting_text' => 'The run may be waiting for QA, Document Owner approval, or assignment of a missing Document Owner. In that case it is not necessarily blocked by an error, but waiting for the next control or decision.',
        'runs_page_help_section_actions' => 'What should I do?',
        'runs_page_help_item_actions_active_title' => 'When a run is active',
        'runs_page_help_item_actions_active_text' => 'Check activity and last progress, and let the processing continue if the values are still updating.',
        'runs_page_help_item_actions_qa_title' => 'When the run waits for QA',
        'runs_page_help_item_actions_qa_text' => 'Open the relevant quality or QA view and complete the authorized control.',
        'runs_page_help_item_actions_owner_title' => 'When the run waits for the Document Owner',
        'runs_page_help_item_actions_owner_text' => 'The Document Owner opens the relevant Wiki page, reviews the material and sources, and chooses Approve or Reject.',
        'runs_page_help_item_actions_fail_title' => 'When the run fails',
        'runs_page_help_item_actions_fail_text' => 'Read the user-facing error explanation, check which document and step were affected, and use any existing retry or regeneration in the UI if it exists.',
        'runs_page_help_item_actions_cancel_title' => 'Cancel run',
        'runs_page_help_item_actions_cancel_text' => 'If a run keeps waiting without progressing — for example on a Document Owner who is unavailable — a System Owner or the source document\'s Document Owner can use Cancel run to stop it. Wiki content already generated is kept, and the source document then becomes deletable.',
        'help_button' => 'How Wiki pages work',
        'help_title' => 'How Wiki pages work',
        'help_intro' => 'This page explains how source documents become Wiki pages, how Document Owners approve the material, and why some statuses can show that the system is still synchronizing.',
        'help_back_to_wiki' => 'Back to Wiki pages',
        'help' => [
            'title' => 'How Wiki pages work',
            'intro' => 'When you upload a source document, Procynia builds a Wiki page with subject matter content, control points, and approval tasks. The page shows both what is already finished and what still needs approval.',
            'back_to_wiki' => 'Back to Wiki pages',
            'sections' => [
                [
                    'title' => 'From source document to Wiki page',
                    'items' => [
                        [
                            'title' => '1. The document is loaded',
                            'text' => 'The source document provides the basis for the new Wiki page. Its content is read and used to build a subject-matter draft.',
                        ],
                        [
                            'title' => '2. The page is structured',
                            'text' => 'Procynia splits the content into subject-matter sections, claims, and control points so the page is easy to read and review.',
                        ],
                        [
                            'title' => '3. Claims and quality control',
                            'text' => 'The system checks that the claims on the page can actually be traced back to the source basis, and that the material meets the expected quality before it moves on.',
                        ],
                    ],
                ],
                [
                    'title' => 'Document Owner and approval',
                    'items' => [
                        [
                            'title' => 'What the Document Owner approves',
                            'text' => 'The Document Owner approves that the Wiki page uses the document correctly and that the content is grounded in what the document actually says.',
                        ],
                        [
                            'title' => 'The approval task',
                            'text' => 'When a Wiki page uses a document, the Document Owner can receive an approval task. It shows that the material is waiting for review before it can be treated as approved.',
                        ],
                        [
                            'title' => 'Approved material',
                            'text' => 'When the Document Owner approves, the page remains approved material for the company. If the page changes later, a new review may be needed.',
                        ],
                    ],
                ],
                [
                    'title' => 'Why multiple owners?',
                    'items' => [
                        [
                            'title' => 'One page can use several documents',
                            'text' => 'A Wiki page can use more than one source document. In that case, more than one Document Owner is involved because each person owns their own source basis.',
                        ],
                        [
                            'title' => 'Each owner reviews their own basis',
                            'text' => 'If a page is built from multiple sources, one owner can be ready while another is still waiting. The status then shows where the page stands overall.',
                        ],
                    ],
                ],
                [
                    'title' => 'What the statuses mean',
                    'items' => [
                        [
                            'title' => 'Article status and Document Owner status are different things',
                            'text' => 'A Wiki page can be a draft, under review, or approved. At the same time, the Document Owner can be pending, approved, or rejected. The two statuses therefore describe different parts of the workflow.',
                        ],
                        [
                            'title' => 'Awaiting sync',
                            'text' => 'This status means the system has not yet fully updated the link between the page content and the approval basis. It does not necessarily mean the content is wrong, only that the update is not finished yet.',
                        ],
                        [
                            'title' => 'Missing Document Owner',
                            'text' => 'This means a source document does not yet have an assigned Document Owner, so the page does not have a complete approval basis yet.',
                        ],
                        [
                            'title' => 'Rejected',
                            'text' => 'The Document Owner believes the material cannot be approved as it stands, and the page must be adjusted before it can move on.',
                        ],
                    ],
                ],
                [
                    'title' => 'When something changes',
                    'items' => [
                        [
                            'title' => 'Changed document content',
                            'text' => 'If a source document changes, it can affect which Wiki pages are still correctly grounded in that document. The approvals then need to be reviewed again.',
                        ],
                        [
                            'title' => 'New or changed Document Owner',
                            'text' => 'If ownership on a document changes, the system must update which people should receive approval tasks for the pages that use that document.',
                        ],
                        [
                            'title' => 'The workflow is updated',
                            'text' => 'When the basis changes, the processing run and the statuses can be updated so the page reflects what is actually approved now.',
                        ],
                    ],
                ],
                [
                    'title' => 'Quick rule of thumb',
                    'items' => [
                        [
                            'title' => 'Source basis first, approval second',
                            'text' => 'First you upload the document. Then the Wiki page is built, checked, and approved by the Document Owner before the material is considered ready.',
                        ],
                        [
                            'title' => 'The statuses should help you understand where the page stands',
                            'text' => 'Use the statuses to see whether the page is finished, waiting for approval, or needs an update after changes in the source documents.',
                        ],
                    ],
                ],
            ],
        ],
